void initDisplay() {
  Serial.begin(115200);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println(F("SSD1306 allocation failed"));
    for (;;);
  }
  display.setRotation(0);
  display.clearDisplay();
  display.display();
}

bool handleIntroScreen() {
  static uint16_t frameIdx = 0;
  static unsigned long lastMs = 0;
  const uint8_t* frames[] = {frame0, frame1, frame2, frame3, frame4, frame5, frame6, frame7, frame8, frame9, frame10, frame11, frame12, frame13, frame14, frame15, frame16, frame17, frame18, frame19, frame20, frame21, frame22, frame23, frame24, frame25, frame26, frame27, frame28, frame29, frame30, frame31, frame32, frame33, frame34, frame35, frame36, frame37, frame38, frame39, frame40, frame41, frame42, frame43, frame44, frame45, frame46, frame47, frame48, frame49, frame50, frame51, frame52, frame53, frame54, frame55, frame56, frame57, frame58, frame59, frame60, frame61, frame62, frame63};
  const uint16_t numFrames = 64;
  if (millis() - lastMs >= 125) {
    lastMs = millis();

    display.clearDisplay();
    display.drawBitmap(0, 0, (const uint8_t*)pgm_read_ptr(&frames[frameIdx]), 128, 64, SSD1306_WHITE);
    display.display();

    frameIdx++;

    // เช็กเมื่อเล่นจบเฟรมสุดท้าย
    if (frameIdx >= numFrames) {
      frameIdx = 0; // รีเซ็ตเฟรมเตรียมไว้
      return true;  // ส่งสัญญาณบอกว่า "จบแล้ว!"
    }
  }

  return false; // ยังเล่นไม่จบ
}